<?php
declare(strict_types=1);
$copyNonce=base64_encode(random_bytes(18));
ini_set('display_errors','0');header('Cache-Control: no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header("Content-Security-Policy: default-src 'none'; script-src 'nonce-{$copyNonce}'; style-src 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'");
ini_set('session.use_strict_mode','1');session_name('ofa_approval');session_set_cookie_params(['secure'=>true,'httponly'=>true,'samesite'=>'Strict','path'=>'/']);session_start();
require __DIR__.'/rewards.php';
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
$error='';$done=false;$o=null;
try{
 $db=rwDb();$id=(string)($_POST['id']??$_GET['id']??'');$token=(string)($_POST['token']??$_GET['token']??'');
 if(!preg_match('/^[a-f0-9]{64}$/D',$token))throw new RuntimeException('Invalid approval link.');
 $q=$db->prepare('SELECT * FROM reward_orders WHERE id=? AND approval_hash=?');$q->execute([$id,hash('sha256',$token)]);$o=$q->fetch(PDO::FETCH_ASSOC);if(!$o)throw new RuntimeException('Order not found.');
 if(!isset($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));
 if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??''))||($_POST['checked']??'')!=='yes')throw new RuntimeException('Confirm that you checked the incoming payment.');
 $o=rwApprove($db,$id,$token);$done=true;
 }
}catch(Throwable $e){http_response_code(400);$error=$e instanceof PDOException?'Order storage unavailable.':$e->getMessage();}
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>One For All — Payment review</title><style>body{background:#11121b;color:#eee;font:16px system-ui;margin:0;padding:30px 16px}main{max-width:700px;margin:auto;background:#202130;border:1px solid #45435e;border-radius:20px;padding:28px}h1{font-size:26px}small,p{color:#bcb9d1}button{background:#7759e7;border:0;border-radius:10px;padding:15px 22px;color:white;font-weight:700;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px system-ui;background:#14151f;padding:18px;border-radius:12px}label{display:block;margin:22px 0;line-height:1.6}.ok{color:#9cdea8}.error{color:#ffb6b6}.copy-actions{display:flex;flex-wrap:wrap;gap:8px}.copy-actions button,.game-row button{padding:12px;background:#bac8ff;color:#101a30}.game-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:16px 0;border-bottom:1px solid #344360}.game-row div{min-width:0;overflow-wrap:anywhere}.game-row button{flex-shrink:0}body{background:#0c1425}main{background:#17243b;border-color:#344360}h2,h3{color:#bac8ff}button{min-height:44px}summary{cursor:pointer;padding:16px 0}@media(max-width:480px){main{padding:18px}body{padding:12px}.game-row{align-items:flex-start}} </style><main><small>ONEFORALL · SELLER PAYMENT REVIEW</small><h1>Verify incoming payment</h1><p>This private link authorizes payment approval. Do not forward it to customers. Verify the actual bank or KPay transfer before approving.</p><?php if($error):?><p class="error"><?=h($error)?></p><?php elseif($o):?><h2 id="copyOrderId"><?=h($o['id'])?></h2><div class="copy-actions"><button type="button" data-copy="copyOrderId">Copy order ID</button><button type="button" data-copy="copyGameList">Copy game list</button><button type="button" data-copy="copyReceipt">Copy receipt</button></div><p id="copyStatus" role="status" aria-live="polite"></p><h3>Games in this order</h3><div id="copyGameList"><?php foreach(json_decode($o['items'],true)?:[] as $i=>$item):?><div class="game-row"><div><strong id="gameTitle<?= (int)$i ?>"><?=h($item['title'])?></strong><br><small><?=h($item['type'])?> · Qty <?= (int)$item['quantity'] ?></small></div><button type="button" data-copy="gameTitle<?= (int)$i ?>">Copy name</button></div><?php endforeach;?></div><p>Total: <strong><?=h(number_format((int)$o['total']/($o['currency']==='THB'?100:1),$o['currency']==='THB'?2:0))?> <?=h($o['currency'])?></strong></p><p>Points after approval: <?=$o['customer']?(int)$o['points']:'0 (guest order)'?></p><details><summary>View customer receipt</summary><pre id="copyReceipt"><?=h($o['receipt'])?></pre></details><?php if($done||$o['status']==='payment_verified'):?><p class="ok">Payment verified. Account points were awarded once. Delivery remains manual through Telegram.</p><?php else:?><form method="post"><input type="hidden" name="id" value="<?=h($id)?>"><input type="hidden" name="token" value="<?=h($token)?>"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><label><input type="checkbox" name="checked" value="yes" required> I have checked the actual incoming payment and the order details.</label><button type="submit">Approve payment & award points</button></form><?php endif;endif;?></main></html>

<script nonce="<?=h($copyNonce)?>">document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const el=document.getElementById(button.dataset.copy);const text=button.dataset.copy==='copyGameList'?Array.from(el.querySelectorAll('.game-row > div')).map(row=>row.innerText).join('\n\n'):el.textContent;try{await navigator.clipboard.writeText(text);document.getElementById('copyStatus').textContent='Copied to clipboard.';}catch(e){const range=document.createRange();range.selectNodeContents(el);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);document.getElementById('copyStatus').textContent='Copy unavailable. Text selected—press and hold to copy.';}}));</script>
